CREATE OR REPLACE FUNCTION public.cc_account_deletion_process(p_id bigint, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r app_private.account_deletion_requests; v_done jsonb := '{}'::jsonb; n int;
begin
  if not (public.has_global_permission('carriers.approve') or public.has_global_permission('finance.approve')) then
    raise exception 'not authorized' using errcode='42501';
  end if;
  if p_action IS NULL OR p_action NOT IN ('reject','complete') then
    raise exception 'unknown action' using errcode='22023';
  end if;
  select * into r from app_private.account_deletion_requests where id = p_id FOR UPDATE;
  if r.id is null then raise exception 'request not found' using errcode='22023'; end if;
  if r.status <> 'requested' then raise exception 'request already %', r.status using errcode='22023'; end if;

  if p_action = 'reject' then
    if coalesce(trim(coalesce(p_note,'')),'') = '' then
      raise exception 'a reason is required to reject' using errcode='22023';
    end if;
    update app_private.account_deletion_requests
       set status='rejected', processed_at=now(), processed_by=auth.uid(), note=p_note where id=p_id;
    return jsonb_build_object('ok', true, 'status','rejected');
  end if;


  -- Inventory must survive a blocked attempt; return a structured refusal, not an exception.
  -- File removal/retention proof is a later reviewed workflow; no bypass flag is exposed.
  n := app_private.capture_account_erasure_inventory(p_id);
  if n > 0 then
    return jsonb_build_object('ok',false,'status','requested','code','ERASURE_REVIEW_REQUIRED',
      'error','File review is required before account deletion can be completed.','file_references',n);
  end if;

  -- 1) contact details
  update public.profiles
     set email = 'deleted+' || r.user_id::text || '@deleted.invalid',
         contact_name = null, phone = null, company = 'Deleted account'
   where id = r.user_id;
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('profile', n);

  -- 2) agent payout + tax + address block (holds IBAN, wallet, DOB, ID doc refs)
  update app_private.agent_profiles
     set full_name='Deleted account', phone=null, street=null, zip=null, city=null,
         state=null, country=null, payout_details='{}'::jsonb, tax_id_last4=null
   where user_id = r.user_id;
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('agent_profile', n);

  -- 3) banking for every org this user owns
  update app_private.org_payment_profiles p
     set account_number='', bank_name='', account_title='',
         verified=false, verified_by=null, verified_at=null,
         routing_number=null, tax_id=null, swift_bic=null,
         bank_address=null, beneficiary_address=null, remittance_email=null, bank_phone=null
   where exists (select 1 from public.organizations o
                  where o.id = p.org_id and o.owner_user_id = r.user_id);
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('payment_profiles', n);

  -- 4) document metadata belongs to profiles(id), not organizations(id).
  -- Storage objects and retained transaction records require separate lifecycle handling.
  delete from public.documents d where d.carrier_id = r.user_id;
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('documents', n);

  -- 5) conversations and messages
  update app_private.lc_conversations set email=null, name=null where user_id = r.user_id;
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('chats', n);
  delete from app_private.agent_messages where user_id = r.user_id;
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('agent_messages', n);

  -- Keep the minimal existing marketing opt-out after contact deletion.
  -- Never overwrite a stronger bounce/complaint/manual suppression.
  if nullif(btrim(r.email),'') is not null then
    insert into app_private.suppressions(channel,address,reason)
    select 'email',lower(btrim(r.email)),'unsubscribed'
    where not exists (select 1 from app_private.suppressions s
      where s.channel='email' and lower(btrim(s.address))=lower(btrim(r.email)));
    update app_private.message_deliveries
       set status='unsubscribed',failure_reason='account deletion marketing suppression',updated_at=now()
     where channel='email' and lower(btrim(recipient_email))=lower(btrim(r.email))
       and (coalesce(template_key ~* '^outreach[._-]',false) or source='campaign')
       and status in ('queued','claimed','scheduled');
  end if;

  -- 6) matching marketing/CRM rows only. A missing email must not match blank contacts.
  -- Complete storage erasure and session handling remain separate audit work.
  -- Cleanup failures must abort the transaction, never report partial erasure as completed.
  delete from app_private.crm_contacts where lower(email) = lower(nullif(btrim(r.email),''));
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('crm_contacts', n);
  delete from app_private.outreach_contacts where lower(email) = lower(nullif(btrim(r.email),''));
  get diagnostics n = row_count; v_done := v_done || jsonb_build_object('outreach_contacts', n);

  begin perform app_private.detach_carrier_drivers(o.id, 'deleted') from public.organizations o where o.owner_user_id = r.user_id and o.kind = 'carrier'; exception when others then null; end;
  -- 7) close the login. The auth row is kept (not dropped) so the retained financial
  --    records keep a stable foreign key — but it can never be signed into again.
  update auth.users
     set encrypted_password = extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),
         email = 'deleted+' || r.user_id::text || '@deleted.invalid',
         phone = null, raw_user_meta_data = '{}'::jsonb,
         banned_until = 'infinity', updated_at = now()
   where id = r.user_id;

  update app_private.account_deletion_requests
     set status='completed', processed_at=now(), processed_by=auth.uid(),
         note = coalesce(p_note,'') || ' | erased: ' || v_done::text
   where id = p_id;

  return jsonb_build_object('ok', true, 'status','completed', 'erased', v_done);
end $function$

CREATE OR REPLACE FUNCTION public.cc_agent_payout_verify(p_user uuid, p_ok boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_email text; v_name text;
begin
  perform app_private.assert_payment_session();
  if not (public.has_global_permission('finance.approve') or public.has_global_permission('carriers.approve')) then
    raise exception 'not authorized' using errcode='42501';
  end if;
  if p_ok is null then raise exception 'an explicit approve or reject decision is required' using errcode='22023'; end if;
  if not p_ok and coalesce(trim(p_reason),'') = '' then
    raise exception 'rejection reason required' using errcode='22023';
  end if;
  update app_private.agent_profiles set
    payout_details = coalesce(payout_details,'{}'::jsonb) || jsonb_build_object(
      'payout_status', case when p_ok then 'verified' else 'rejected' end,
      'payout_reason', p_reason,
      'payout_reviewed_at', now()),
    updated_at = now()
  where user_id = p_user;
  if not found then raise exception 'agent profile not found' using errcode='22023'; end if;
  begin
    insert into app_private.notifications(recipient_user, channel, template_key, payload, status, sent_at)
    values (p_user, 'in_app', 'agent.payout_review', jsonb_build_object(
      'title', case when p_ok then '✓ Payout details verified' else '✕ Payout details need a fix' end,
      'body', coalesce(p_reason, case when p_ok then 'Your payout method is verified — payouts can be sent here.' else 'Please review and correct your payout details.' end),
      'tone', case when p_ok then 'success' else 'urgent' end, 'url', '/app/agent/#verify'), 'sent', now());
  exception when others then null; end;
  if not p_ok then
    begin
      select email into v_email from auth.users where id = p_user;
      if v_email is not null then
        perform app_private.sys_email(v_email, 'agent.payout_review', '✕ Payout details need a correction',
          '<div style="font-family:Inter,Arial,sans-serif"><h2>Your payout details need a correction</h2><p><b>Reason:</b> ' || p_reason || '</p><p>Open your Verification Center and update your payout method — it goes straight back to review.</p><p><a href="https://loadboot.com/app/agent/#verify" style="background:#FC5305;color:#fff;padding:11px 20px;border-radius:9px;text-decoration:none;font-weight:800">Fix it now &rarr;</a></p></div>',
          null, 'agentpayout:' || p_user::text || ':' || to_char(now(),'YYYYMMDDHH24MI'));
      end if;
    exception when others then null; end;
  end if;
  return jsonb_build_object('ok', true, 'verified', p_ok);
end $function$

CREATE OR REPLACE FUNCTION public.cc_delivery_worker_unsubscribe(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare
  d app_private.message_deliveries%rowtype;
  v_email text;
begin
  select * into d
    from app_private.message_deliveries
   where correlation_id = p_token
   limit 1;

  if d.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown token');
  end if;

  if d.channel = 'email' and d.recipient_email is not null then
    v_email := lower(trim(d.recipient_email));
    if v_email = '' or v_email !~ '^[^@]+@[^@]+[.][^@]+$' then
      return jsonb_build_object('ok', false, 'reason', 'invalid recipient');
    end if;

    -- A token from an older operational email remains a valid way to opt out of marketing,
    -- but it never suppresses operational delivery or rewrites that operational row.
    insert into app_private.suppressions(channel, address, reason)
    select 'email', v_email, 'unsubscribed'
    where not exists (select 1 from app_private.suppressions s where s.channel='email' and lower(btrim(s.address))=v_email);

    update app_private.outreach_contacts
       set status = 'unsubscribed'
     where lower(trim(email)) = v_email
       and status <> 'unsubscribed';

    update app_private.message_deliveries
       set status = 'unsubscribed',
           failure_reason = 'recipient opted out of marketing/outreach',
           updated_at = now()
     where channel = 'email'
       and lower(btrim(recipient_email)) = v_email
       and (template_key ~* '^outreach[._-]' or source = 'campaign')
       and status in ('queued', 'claimed', 'scheduled');



    perform app_private.log_audit(
      'comm.outreach_unsubscribe', 'delivery', d.id::text, null,
      'recipient unsubscribed through one-click link',
      jsonb_build_object('channel', 'email', 'scope', 'marketing')
    );

    return jsonb_build_object('ok', true, 'channel', 'email', 'scope', 'marketing');
  elsif d.channel = 'sms' and d.recipient_phone is not null then
    insert into app_private.suppressions(channel, address, reason)
    values ('sms', d.recipient_phone, 'unsubscribed')
    on conflict do nothing;

    update app_private.message_deliveries
       set status = 'unsubscribed', updated_at = now()
     where id = d.id and status in ('queued', 'claimed', 'scheduled');

    perform app_private.log_audit(
      'comm.unsubscribe', 'delivery', d.id::text, null,
      'recipient unsubscribed from SMS through one-click link',
      jsonb_build_object('channel', 'sms')
    );

    return jsonb_build_object('ok', true, 'channel', 'sms');
  end if;

  return jsonb_build_object('ok', false, 'reason', 'unsupported channel');
end;
$function$

CREATE OR REPLACE FUNCTION public.cc_enqueue_transactional(p_channel text, p_email text, p_template_key text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_idem text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private, public'
AS $function$
declare v_key text; v_sched timestamptz; v_id uuid; v_ins int; v_provider text; v_addr text;
begin
  if not app_private.can_manage_comms() then raise exception 'not authorized' using errcode='42501'; end if;
  if p_channel not in ('email','sms') then raise exception 'invalid channel' using errcode='22023'; end if;
  if p_channel='email' then
    if p_email is null or p_email !~ '^[^@]+@[^@]+\.[^@]+$' then raise exception 'invalid email recipient' using errcode='22023'; end if;
    v_addr := lower(p_email); v_provider := 'resend';
  else
    if p_email is null or p_email !~ '^\+?[0-9]{7,15}$' then raise exception 'invalid sms recipient' using errcode='22023'; end if;
    v_addr := p_email; v_provider := 'twilio';
  end if;
  if exists (select 1 from app_private.suppressions where channel=p_channel and lower(btrim(address))=lower(btrim(v_addr))
    and (p_channel <> 'email' or reason IS DISTINCT FROM 'unsubscribed'
         or coalesce(p_template_key ~* '^outreach[._-]',false))) then
    return jsonb_build_object('queued',false,'reason','suppressed'); end if;
  v_sched := coalesce(p_scheduled_at, now());
  v_key := coalesce(p_idem, 'txn:'||p_channel||':'||lower(v_addr)||':'||coalesce(p_template_key,'')||':'||extract(epoch from v_sched)::bigint::text);
  insert into app_private.message_deliveries(source,channel,provider,recipient_email,recipient_phone,idempotency_key,status,scheduled_at,template_key,meta)
  values ('transactional',p_channel,v_provider,
    case when p_channel='email' then v_addr else null end,
    case when p_channel='sms'   then v_addr else null end,
    v_key, case when v_sched>now() then 'scheduled' else 'queued' end, v_sched, p_template_key,
    coalesce(p_meta,'{}'::jsonb) || jsonb_build_object('subject',p_subject))
  on conflict (idempotency_key) do nothing returning id into v_id;
  get diagnostics v_ins = row_count;
  return jsonb_build_object('queued', v_ins>0, 'delivery_id', v_id, 'idempotency_key', v_key, 'channel', p_channel,
    'status', case when v_ins=0 then 'duplicate' when v_sched>now() then 'scheduled' else 'queued' end);
end; $function$

CREATE OR REPLACE FUNCTION public.lc_ob_save(p_visitor_key text, p_conversation_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_step_key text DEFAULT NULL::text, p_patch jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text, p_account_email text DEFAULT NULL::text, p_account_created boolean DEFAULT NULL::boolean, p_completed boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_id uuid; v_max integer; v_seconds integer; v_now timestamptz; v_started timestamptz; v_hash text;
begin
  if coalesce(length(p_visitor_key),0) not between 16 and 64 or p_visitor_key like 'novkey%' then return jsonb_build_object('error','bad key'); end if;
  -- A supplied link must belong to this visitor and, for account chats, this user.
  if p_conversation_id is not null and not exists (
    select 1 from app_private.lc_conversations c
    where c.id = p_conversation_id and c.visitor_key = p_visitor_key
      and (c.user_id is null or c.user_id = auth.uid())
  ) then return jsonb_build_object('error','not found'); end if;
  -- Do not bypass a saved account-chat binding by omitting/replacing the supplied link.
  if exists (
    select 1 from app_private.lc_onboarding o
    where o.visitor_key = p_visitor_key and o.conversation_id is not null
      and not exists (
        select 1 from app_private.lc_conversations c
        where c.id = o.conversation_id and c.visitor_key = p_visitor_key
          and (c.user_id is null or c.user_id = auth.uid())
      )
  ) then return jsonb_build_object('error','not found'); end if;
  if p_role is not null and p_role not in ('carrier','broker','shipper','dispatcher','agent') then
    return jsonb_build_object('error','bad role'); end if;
  if p_patch is not null and pg_column_size(p_patch) > 16384 then return jsonb_build_object('error','too big'); end if;
  select max_saves,window_seconds into v_max,v_seconds from app_private.lc_save_limit_config where id;
  if not found then return jsonb_build_object('error','save temporarily unavailable','retry_after',60); end if;
  v_now := clock_timestamp();
  v_hash := encode(sha256(convert_to(p_visitor_key,'UTF8')),'hex');
  -- A single atomic upsert serializes competing calls for this visitor. Refused calls don't save data or notes.
  insert into app_private.lc_save_windows as w(visitor_hash,window_started,saves) values(v_hash,v_now,1)
  on conflict(visitor_hash) do update set
    window_started=case when w.window_started+make_interval(secs=>v_seconds)<=v_now then v_now else w.window_started end,
    saves=case when w.window_started+make_interval(secs=>v_seconds)<=v_now then 1 else w.saves+1 end
  where w.window_started+make_interval(secs=>v_seconds)<=v_now or w.saves<v_max
  returning window_started into v_started;
  if not found then
    select window_started into v_started from app_private.lc_save_windows where visitor_hash=v_hash;
    return jsonb_build_object('error','rate_limit','retry_after',greatest(1,ceil(extract(epoch from v_started+make_interval(secs=>v_seconds)-v_now))::integer));
  end if;
  -- Bounded lazy cleanup; no scheduled sender/job and no visitor secret stored here.
  delete from app_private.lc_save_windows where visitor_hash in
    (select visitor_hash from app_private.lc_save_windows where window_started<v_now-interval '1 day' order by window_started limit 100 for update skip locked);
  insert into app_private.lc_onboarding as o (visitor_key, conversation_id, role, step_key, data)
  values (p_visitor_key, p_conversation_id, p_role, coalesce(p_step_key,'role'), coalesce(p_patch,'{}'::jsonb))
  on conflict (visitor_key) do update set
    conversation_id = coalesce(excluded.conversation_id, o.conversation_id),
    role = coalesce(excluded.role, o.role),
    step_key = coalesce(p_step_key, o.step_key),
    data = case when p_patch is null then o.data else o.data || p_patch end,
    account_email = coalesce(p_account_email, o.account_email),
    account_created = coalesce(p_account_created, o.account_created),
    completed_at = case when p_completed is true then coalesce(o.completed_at, now()) else o.completed_at end,
    updated_at = now()
  returning id into v_id;
  if p_account_email is not null or p_account_created is not null or p_completed is not null then
    update app_private.lc_onboarding set
      account_email = coalesce(p_account_email, account_email),
      account_created = coalesce(p_account_created, account_created),
      completed_at = case when p_completed is true then coalesce(completed_at, now()) else completed_at end
    where id = v_id;
  end if;
  if p_note is not null and p_conversation_id is not null then
    if exists (select 1 from app_private.lc_conversations c
               where c.id = p_conversation_id and c.visitor_key = p_visitor_key) then
      insert into app_private.lc_messages (conversation_id, sender, body)
      values (p_conversation_id, 'bot', '[[note]] ' || left(p_note, 590));
      update app_private.lc_conversations set last_msg_at = now(),
        lead_stage = coalesce(lead_stage,'new') where id = p_conversation_id;
    end if;
  end if;
  return jsonb_build_object('ok', true);
end $function$
